import{c as e,Q as a,j as l,m as i}from"./chunks/framework.DOi4mjdC.js";const p=JSON.parse('{"title":"SetReduceType","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetReduceType","slug":"setreducetype"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/SetReduceType.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/SetReduceType.md"}'),d={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/SetReduceType.md"};function n(r,t,s,o,c,h){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="setreducetype" tabindex="-1">SetReduceType <a class="header-anchor" href="#setreducetype" aria-label="Permalink to &quot;SetReduceType&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置Reduce操作类型，仅对有归约操作的通信任务生效。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t SetReduceType(uint32_t reduceType, uint8_t dstDataType = 0, uint8_t srcDataType = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>reduceType</td><td>输入</td><td>归约操作类型，仅对有归约操作的通信任务生效。uint32_t类型，取值详见表2参数说明。</td></tr><tr><td>dstDataType</td><td>输入</td><td>通信任务中输出数据的数据类型。uint8_t类型，该参数的取值范围请参考表1。 Ascend 950PR/Ascend 950DT，不同通信任务支持的输出数据类型不同，具体为： 对于AllReduce、AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：输出的数据类型必须与输入的数据类型一致。各通信任务支持的输入数据类型请参考srcDataType。对于ReduceScatter通信任务，当输入的数据类型为int16_t、int32_t、half、float、bfloat16_t时，输出的数据类型必须与其一致；当输入的数据类型为int8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t时，输出的数据类型必须为half、bfloat16_t、float三者之一。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，该参数暂不支持，配置后不生效。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，该参数暂不支持，配置后不生效。</td></tr><tr><td>srcDataType</td><td>输入</td><td>通信任务中输入数据的数据类型。uint8_t类型，该参数的取值范围请参考表1。 Ascend 950PR/Ascend 950DT，不同通信任务支持的输入数据类型如下： AllReduce通信任务：支持的输入类型为int16_t、half、bfloat16_t、int32_t、float。AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：支持的输入类型为int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、double。ReduceScatter通信任务：支持的输入类型为int8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、half、bfloat16_t、int32_t、float。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，该参数暂不支持，配置后不生效。 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，该参数暂不支持，配置后不生效。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><ul><li>0表示设置成功。</li><li>非0表示设置失败。</li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本接口的调用示例请见<a href="./SetOpType.html#section1665082013318">调用示例</a>。</p>',14)])])}const _=e(d,[["render",n]]);export{p as __pageData,_ as default};
